SELECT parking_id
FROM cctv_status_log
WHERE id = #{cameraId}

SELECT id, camera_name, location, status, last_checked_at, last_connected, record_status, log_type, created_at FROM cctv_status_log
AND status = #{dto.status}
AND log_type = #{dto.logType}
AND camera_name LIKE CONCAT('%', #{dto.cameraName}, '%')
AND ( camera_name LIKE CONCAT('%', #{dto.keyword}, '%') OR location LIKE CONCAT('%', #{dto.keyword}, '%') OR status LIKE CONCAT('%', #{dto.keyword}, '%') )
ORDER BY last_checked_at DESC LIMIT #{limit} OFFSET #{offset}

